            break
    return rc


def cmd_call(args) -> int:
    """Raw call: drive.py call ext.nothingness.<method> [k=v ...]"""
    params: dict[str, Any] = {}
    for kv in args.kvs or []:
        if "=" not in kv:
            print(f"bad param {kv!r}", file=sys.stderr)
            return 2
        k, v = kv.split("=", 1)
        params[k] = v
    res = _ext_resilient(args.method, params)
    print(json.dumps(res, indent=2))
    return 0


